const {Kafka}=require('kafkajs');class Consumer{constructor(db){this.db=db;this.kafka=new Kafka({clientId:'merchant-analytics',brokers:(process.env.KAFKA_BROKERS||'localhost:9092').split(',')})}async start(){const c=this.kafka.consumer({groupId:'merchant-analytics'});await c.connect();await c.subscribe({topics:['payment-events','transfer-events']});await c.run({eachMessage:async({topic,message})=>{let payload;try{payload=JSON.parse(message.value.toString())}catch{payload={raw:message.value.toString()}}await this.db.collection('analytics_events').insertOne({topic,payload,receivedAt:new Date()})}})}}module.exports=Consumer;
